export interface ConnectorConfig {
  /** Brevo API key from environment variable BREVO_API_KEY */
  apiKey: string
  /** Optional list IDs to subscribe the contact to. If not provided, no list subscription occurs. */
  listIds?: number[]
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface BrevoContactResult {
  id: number
}

function extractEmail(payload: TypeformWebhookPayload): string {
  const emailAnswer = payload.form_response.answers.find(
    (a) => a.field.type === 'email' && a.email
  )
  if (!emailAnswer?.email) {
    throw new Error('Required email field not found in Typeform response answers')
  }
  return emailAnswer.email
}

function extractName(payload: TypeformWebhookPayload): string {
  const nameAnswer = payload.form_response.answers.find(
    (a) => a.field.type === 'short_text' && a.text
  )
  if (!nameAnswer?.text) {
    throw new Error('Required name field (short_text) not found in Typeform response answers')
  }
  return nameAnswer.text
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig
): Promise<BrevoContactResult> {
  const fetchImpl = config.fetch ?? fetch

  const email = extractEmail(payload)
  const name = extractName(payload)

  const body = {
    email,
    attributes: {
      FULLNAME: name
    },
    listIds: config.listIds ?? []
  }

  const response = await fetchImpl('https://api.brevo.com/v3/contacts', {
    method: 'POST',
    headers: {
      'api-key': config.apiKey,
      'Content-Type': 'application/json',
      Accept: 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`Brevo API error: Error(`Brevo API request failed: ${response.status} ${response.statusText} for POST https://api.brevo.com/v3/contacts`)
  }

  const result = (await response.json()) as BrevoContactResult
  return result
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      apiKey: 'test-api-key',
      listIds: [1],
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result).toEqual({ id: 123 })
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.brevo.com/v3/contacts')
    expect(calls[0].json).toEqual({
      email: 'laura@example.com',
      attributes: { FULLNAME: 'Laura' },
      listIds: [1]
    })
    expect(calls[0].headers.get('api-key')).toBe('test-api-key')
  })
})

